sys_ux_client_script.script:
function handler({api}) {

  const user = api.context.session.user;

  // wait until login is complete
  if (!user || !user.roles) {
    setTimeout(() => handler({api}), 1000);
    return;
  }

  const roles = user.roles;

  if (roles.includes('x_1909965_almaconn.admin')) {
    window.location.replace('/x/1909965/admin-portal/dashboard');
    return;
  }

  if (roles.includes('x_1909965_almaconn.alumni_user')) {
    window.location.replace('/x/1909965/alumni-portal/dashboard');
    return;
  }

  if (roles.includes('x_1909965_almaconn.Student')) {
    window.location.replace('/x/1909965/almaconnect/student-dashboard');
    return;
  }

}
